function PTNV_Main()
	PTNV_Load()
	local a = PTNV_Active()
	local o = {}
	o[1] = PTNV_TM_CUR .. " (" .. a.n .. ")/PTNV_AP1"
	o[2] = PTNV_GR[2].title .. "/PTNV_P2_1"
	o[3] = PTNV_GR[3].title .. "/PTNV_P3_1"
	o[4] = PTNV_GR[4].title .. "/PTNV_P4_1"
	o[5] = PTNV_GR[5].title .. "/PTNV_P5_1"
	o[6] = PTNV_GR[6].title .. "/PTNV_P6_1"
	o[7] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(PTNV_TM_TITLE .. GetLevel() .. ".", o)
end

function PTNV_ActPage(p)
	PTNV_Load()
	local a = PTNV_Active()
	if a.n == 0 then
		Say(PTNV_TM_NONE, 2, PTNV_T_BACK .. "/main", PTNV_T_CLOSE .. "/PTNV_No")
		return
	end
	local first, last, more = PTNV_Span(a.n, p)
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		local e = a[i]
		local s = PTNV_CH[e.c].title .. ": "
		if e.r.dest and e.r.dest > 0 then s = s .. PTNV_DS[e.r.dest].nm else s = s .. e.r.txt end
		n = n + 1
		o[n] = PTNV_Clip(s, 58) .. "/PTNV_A" .. i
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTNV_AP" .. (p + 1) end
	if p > 1 then n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_AP" .. (p - 1)
	else n = n + 1 o[n] = PTNV_T_BACK .. "/main" end
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(PTNV_TM_CURTITLE, o)
end

function PTNV_Act(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then PTNV_ActPage(1) return end
	local o = {}
	local n = 0
	local s = PTNV_StepText(e)
	if e.r.dest and e.r.dest > 0 then
		n = n + 1
		o[n] = PTNV_Clip(PTNV_TM_GOTO .. PTNV_DS[e.r.dest].nm, 58) .. "/PTNV_AG" .. i
	else
		s = s .. " " .. PTNV_TM_NONPC
	end
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTNV_AP" .. (floor((i - 1) / 4) + 1)
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTNV_No"
	PTNV_Say(PTNV_Clip(s, 500), o)
end

function PTNV_ActGo(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if e and e.r.dest and e.r.dest > 0 then PTNV_Go(e.r.dest) end
end

